      "DNS and HTTPS are ready. Press Make primary to start serving the site at this address.": "DNS 和 HTTPS 已就绪。点击“设为主地址”即可通过此地址提供网站。",
      "Show all models": "显示所有模型",
      "Connected.": "已连接。",
