      "This theme is invalid.": "此主题无效。",
      "Discard the unsaved file edit in this space?": "要放弃此空间中尚未保存的文件编辑吗？",
      "Could not save pinned chats.": "无法保存置顶聊天。",
      "Could not open the conversation this offer was made in": "无法打开发出此邀请的聊天",
      "That theme no longer exists.": "此主题已不存在。",
      "Undone. No file changes to restore.": "已撤销。没有可还原的文件更改。",
      "Cloud panel unavailable": "云端面板不可用",
      "Send a message to start this cloud chat’s terminal": "发送消息以启动此云端聊天的终端",
      "Split right": "向右分屏",
      "Auth analytics period": "身份验证分析周期",
      "No new users in this period.": "此时间段内没有新用户。",
      "No objects on this page yet.": "此页面上还没有对象。",
      "Deploy this environment to add secrets.": "部署此环境后即可添加密钥。",
      "Use an uppercase name starting with a letter, followed by letters, numbers, or underscores (up to 64 characters). Platform names are reserved.": "名称必须以大写字母开头，后接字母、数字或下划线（最多 64 个字符）。平台保留名称不可使用。",
      "Cloudflare could not apply the change. Check deployment activity for details before retrying.": "Cloudflare 无法应用此更改。请查看部署活动了解详情，然后重试。",
      "Could not change publication. Try again.": "无法更改发布状态，请重试。",
      "Could not delete the site.": "无法删除站点。",
      "This subdomain is reserved. Choose another name.": "此子域名已被保留，请选择其他名称。",
      "Could not update your address. Try again.": "无法更新地址，请重试。",
      "Choose a memorable address for your site.": "为站点选择一个容易记住的地址。",
      "This change is still running or needs reconciliation. Check deployment activity before making another change.": "此更改仍在执行或需要协调处理。请先查看部署活动，再进行其他更改。",
      "Could not update the domain. Try again.": "无法更新域名，请重试。",
      "Retry same change": "重试相同更改",
      "Production deployments keep this address. HTTPS renews automatically. Hosting limits and publication settings still apply.": "生产部署会保留此地址。HTTPS 将自动续期。托管额度和发布设置仍然适用。",
      "Your DNS is verified, but HTTPS setup has not completed. Click Check connection for an update. If the check fails, contact support.": "DNS 已验证，但 HTTPS 尚未配置完成。点击“检查连接”查看更新。如果检查失败，请联系支持团队。",
      "Add this record at your DNS provider. The unique target verifies ownership and routes visitors to Freebuff. If your provider appends your domain, enter only the subdomain part as the name (for example, www). Replace conflicting A, AAAA or CNAME records for this hostname only; leave email and other records unchanged.": "请在 DNS 服务商处添加此记录。唯一目标用于验证域名所有权并将访客路由到 Freebuff。如果服务商会自动附加域名，请仅在名称中填写子域名部分（例如 www）。仅替换此主机名冲突的 A、AAAA 或 CNAME 记录；不要更改邮件及其他记录。",
      "DNS and HTTPS are ready.": "DNS 和 HTTPS 已就绪。",
      "Primary domain change details": "主域名更改详情",
      "This disconnects the domain, not the site. Code, data and deployments are kept; your Freebuff URL becomes the default again. Delete the old DNS record afterward. Reconnecting requires a new verification target.": "此操作只会断开域名，不会删除站点。代码、数据和部署都会保留；Freebuff 网址会重新设为默认地址。之后请删除旧 DNS 记录。重新连接时需要新的验证目标。",
      "Clipboard unavailable. Select and copy the record manually.": "剪贴板不可用，请手动选择并复制此记录。",
      "Rows written": "写入行数",
      "Requests, realtime events, CPU time, database reads/writes, and file reads/writes/lists reset on the 1st at 00:00 UTC.": "请求数、实时事件数、CPU 时间、数据库读写次数以及文件读写/列表次数均在 UTC 每月 1 日 00:00 重置。",
      "Serving is paused while we wait for a current usage reading. Sites resume automatically once monitoring confirms they’re within limits.": "正在等待最新用量数据，因此服务暂时暂停。监控确认用量未超出限制后，站点会自动恢复。",
      "None back": "无返回项",
      "My evidence is genuine, and I’ll keep it up — faking it or undoing it later means losing the reward and my account.": "我提交的证据真实有效，并会持续保持；伪造证据或之后撤销操作会导致奖励和账户被取消。",
      "Any OpenAI-compatible SDK works. Point it at the base URL and pass your key.": "任何兼容 OpenAI 的 SDK 都可使用。将其指向基础 URL 并传入密钥即可。",
      "Per 1M tokens. Same price as the provider.": "每 100 万 Token。价格与服务商相同。",
      "Developer API sections": "开发者 API 栏目",
      "A secret cannot contain a NUL byte.": "密钥不能包含 NUL 字节。",
      "NAME": "名称",
      "Give every preview its own database branch, created in about a second.": "为每个预览创建独立数据库分支，约一秒即可完成。",
      "Create projects, branch databases and run SQL from chat.": "在聊天中创建项目、数据库分支并运行 SQL。",
      "Use a public HTTPS image link without a password or custom port.": "请使用无需密码或自定义端口的公开 HTTPS 图片链接。",
      "Saving project": "正在保存项目",
      "The agent is": "智能体状态：",
      "End hour and close": "结束小时额度并关闭",
      "Shown because you just finished a task. Freebuff shows at most one sponsor break a day, and fewer regular ads while you work.": "由于你刚完成一项任务，因此显示此内容。Freebuff 每天最多显示一次赞助内容，并会在你工作时减少常规广告。",
      "Your idea, ready to explore.": "你的创意已准备好开始探索。",
      "Wed": "周三",
      "Sat": "周六",
      "Made for your next idea": "为你的下一个创意而打造",
      "Meet your builder.": "认识你的开发助手。",
      "Greptile. Catch bugs. Before you merge. AI code review with full codebase context. Try Greptile.": "Greptile：在合并前发现问题。结合完整代码库上下文的 AI 代码审查。试试 Greptile。",
      "AI code review with context": "结合上下文的 AI 代码审查",
      "An idea takes shape.": "创意逐渐成形。",
      "Describe it. Runable creates it.": "描述你的想法，Runable 会将其实现。",
      "Panel tall 2:5": "竖版面板 2:5",
      "Panel landscape 16:9": "横版面板 16:9",
      "Simulation only | no navigation or sponsored work started.": "仅为模拟 | 未进行页面跳转，也未启动赞助任务。",
      "Images stay in this browser session. PNG, JPEG, WebP or AVIF, up to 10 MB.": "图片仅保留在此浏览器会话中。支持 PNG、JPEG、WebP 或 AVIF，最大 10 MB。",
      "Strongest price-to-performance models": "性价比最高的模型",
      "Resume your purchased hour": "继续已购买的小时额度",
      "Finish the current turn and clear queued messages to switch providers": "结束当前轮次并清空排队消息后，才能切换服务商",
      "No model is available for this harness right now.": "当前没有适用于此运行环境的模型。",
      "This chat runs in Cloud. Choose Local to continue it on this computer.": "此聊天在云端运行。选择“本地”即可在这台电脑上继续。",
      "Run on this computer in this folder, in a worktree so your folder stays untouched, or in Cloud.": "可在此文件夹中的这台电脑上运行、在工作树中运行以保持文件夹不变，或在云端运行。",
      "Branch to work on in this folder. If another one is checked out, Freebuff asks what to do with it when you send.": "在此文件夹中要操作的分支。如果当前检出的是其他分支，发送时 Freebuff 会询问如何处理。",
      "Daily hours balance unavailable": "每日小时额度余额不可用",
