      "This session used up its full price. A refund returns whole hours of balance it did not spend, never unused time.": "此会话已用完对应的全部价格。退款仅返还未使用的整数小时额度余额，不会返还未使用的时间。",
      "Limited access, verify country": "访问受限，请验证所在国家/地区",
