      "Reporting is unavailable": "报告功能不可用",
      "This folder needs local Git before sponsored work can start. Freebuff can set it up for you. No GitHub account or upload is needed.": "开始赞助任务前，此文件夹需要本地 Git。Freebuff 可以为你完成设置，无需 GitHub 账户，也不会上传文件。",
      "Git metadata": "Git 元数据",
      "Setup could not finish: enter a commit name and a valid email, then approve again.": "设置未能完成：请输入提交者名称和有效电子邮件，然后重新批准。",
      "Preparing a summary of the files to commit…": "正在准备要提交的文件摘要…",
      "Local Git is ready. This sponsored offer still needs a hosted Git remote before it can be considered.": "本地 Git 已就绪。此赞助任务仍需要托管 Git 远程仓库才能进行资格审核。",
      "Recheck, and Freebuff can create a local Git repository with a first commit for you.": "重新检查后，Freebuff 可以为你创建本地 Git 仓库并完成首次提交。",
      "Button links must use http:// or https://": "按钮链接必须使用 http:// 或 https://",
