      "Click a shortcut to change it.": "点击快捷键以更改。",
      "Press a key combination. Esc to cancel.": "请按下组合键。按 Esc 取消。",
      "About this section": "关于此部分",
      "Choose each project separately. Opting in records permission for the selected snapshot; preparation alone does not earn hours.": "请分别选择每个项目。选择加入即表示授权使用所选快照；仅准备项目不会赚取小时额度。",
      "Stop new licensing of this project and request removal of its contribution copies? Existing partner licenses remain valid.": "停止此项目的新授权，并请求移除已有贡献副本？现有合作方许可证仍然有效。",
      "This repo is not available to opt in right now. Refresh and try again.": "此代码仓库目前无法加入。请刷新后重试。",
      "Could not withdraw permission. Please retry.": "无法撤回授权，请重试。",
      "I confirm I starred this repository myself, and that this is genuine proof of it. I understand it will be verified, and that falsified evidence will result in my account being banned.": "我确认该代码仓库是我本人点星的，且此截图为真实凭证。我理解平台会进行核验，伪造证据将导致账户被封禁。",
      "Say something specific about this post, not a generic compliment.": "请针对这条帖子写具体内容，不要只写泛泛的赞美。",
      "The signup is linked to you and GitHub is connected, but eligibility hasn't been verified yet. We'll retry when they sign in.": "该注册已与你关联，且 GitHub 已连接，但资格尚未核验。对方登录后我们会重试。",
      "Copy .env lines": "复制 .env 行",
      "Name it after the app that uses it, and limit its spend if you like.": "可使用调用它的应用名称来命名，也可设置支出限额。",
      "Could not open web settings.": "无法打开网页设置。",
      "Add the instructions the agent should follow for this skill.": "添加智能体在使用此技能时应遵循的指令。",
      "Could not save settings.": "无法保存设置。",
      "Create a Cloud project to configure it here.": "创建云端项目后即可在此配置。",
      "That block has no servers in it.": "此配置块中没有服务器。",
      "Nothing has been contacted yet. Adding this server lets Freebuff talk to this address, and it may ask you to sign in. Its tool list cannot be read without connecting, so you are asked again afterwards about what it may do.": "目前尚未连接任何内容。添加此服务器后，Freebuff 可以访问该地址，服务器可能会要求你登录。连接前无法读取其工具列表，因此连接后系统会再次询问你允许它执行哪些操作。",
      "This image could not be opened. Try a PNG, JPEG, or WebP file.": "无法打开此图片。请尝试 PNG、JPEG 或 WebP 文件。",
      "Image import is unavailable in this window.": "此窗口中无法导入图片。",
      "This sponsored task is not waiting for an account.": "此赞助任务当前不在等待账户验证。",
