      "Collapse left sidebar": "折叠左侧边栏",
      "Can't reach Freebuff's servers on this network — try another connection; turns resume when it's back": "当前网络无法连接 Freebuff 服务器，请尝试其他网络；连接恢复后，轮次会继续。",
