      "Open browser again": "重新打开浏览器",
      "Quality": "质量",
      "Could not open GitHub in your browser.": "无法在浏览器中打开 GitHub。",
      "Sign in to Freebuff to connect Claude Code and Codex.": "登录 Freebuff 以连接 Claude Code 和 Codex。",
      "Couldn’t open your browser.": "无法打开浏览器。",
      "Searching…": "正在搜索…",
      "popout": "弹出窗口",
      "Paste a server’s JSON configuration.": "粘贴服务器的 JSON 配置。",
      "Couldn’t refresh your servers.": "无法刷新服务器列表。",
      "1 week": "1 周",
      "Reach this computer's open threads from your phone: text Freebuff to list them, send them messages and approve commands, and get a text when a turn finishes. Threads sync to your Freebuff account while this is on.": "通过手机访问这台电脑上打开的任务：发送短信至 Freebuff 查看任务、发送消息并批准命令；轮次结束时也会收到短信。开启期间，任务会同步到你的 Freebuff 账户。",
      "This script came with the project's files and won't run until you check it and press Save.": "此脚本随项目文件提供；检查并点击“保存”后才会运行。",
      "Freebuff and the agent otherwise move a chat to Cloud when a task suits it, with a copy of this folder and its development secrets. With this on, every chat stays on this computer and nothing from this folder is uploaded.": "通常在任务适合云端处理时，Freebuff 和智能体会将聊天移至云端，并复制此文件夹及其开发密钥。开启此选项后，所有聊天都会留在这台电脑上，此文件夹中的内容不会上传。",
      "Show mode buttons, skills and context usage in the composer. Slash commands work either way.": "在输入框中显示模式按钮、技能和上下文用量。无论此选项如何设置，斜杠命令都可使用。",
      "Play a sound when a chat finishes or an agent needs your answer or approval.": "聊天结束或智能体需要你回答或批准时播放提示音。",
      "Archive inactive chats after the selected time. Running or queued chats stay active. Restore chats in Settings → Archived.": "在所选时间后归档不活跃的聊天。运行中或排队中的聊天会保持活跃。可在“设置”→“已归档”中恢复聊天。",
      "Auto-archive local chats after": "本地聊天的自动归档时间",
      "Auto-archive cloud chats after": "云端聊天的自动归档时间",
      "Start another hour when a session expires, using hours at the model’s current rate. When off, unfinished runs save their progress and wait for you. Applies to every thread on this device.": "会话到期时，按模型当前费率再开启一小时。关闭后，未完成的运行会保存进度并等待你继续。适用于此设备上的所有任务。",
      "Agents can run administrator commands without asking you first.": "智能体无需事先询问即可运行管理员命令。",
      "Could not load GitHub. Try again.": "无法加载 GitHub，请重试。",
      "Freebuff couldn’t check your GitHub connection.": "Freebuff 无法检查你的 GitHub 连接。",
      "Your repositories are available in cloud chats on web and desktop.": "你的代码仓库可在网页和桌面端的云端聊天中使用。",
      "Refreshing repositories…": "正在刷新代码仓库…",
      "Finish connecting in your browser, then return here.": "请在浏览器中完成连接，然后返回此处。",
      "Saved with your Freebuff account for Cloud chats. Your provider bills you and no Freebuff hours are used. Keys never enter the Cloud VM, transcripts or traces.": "已与你的 Freebuff 账户关联，可用于云端聊天。费用由服务商向你收取，不消耗 Freebuff 小时额度。密钥不会进入云端虚拟机、聊天记录或跟踪记录。",
      "An Anthropic API key runs Claude Code, and its models also run the Freebuff agent under API providers. Saving one replaces a subscription sign-in.": "Anthropic API 密钥可运行 Claude Code，其模型也能作为 API 服务商运行 Freebuff 智能体。保存密钥会替换订阅登录方式。",
