      "About model limits": "关于模型限额",
      "About API providers": "关于 API 服务商",
      "Codex models": "Codex 模型",
      "Tasks keep the old key until you choose this provider again in the model picker.": "在模型选择器中重新选择此服务商之前，任务会继续使用旧密钥。",
      "Open Claude sign-in ↗": "打开 Claude 登录 ↗",
      "Code from Claude": "Claude 提供的代码",
      "Approve in your browser…": "在浏览器中批准…",
