      "Sign in again": "重新登录",
      "Runs Codex in Cloud chats and in Freebuff Desktop, on your OpenAI sign-in or an OpenAI API key.": "在云端聊天和 Freebuff 桌面端运行 Codex，使用 OpenAI 登录或 OpenAI API 密钥。",
      "One connection for your Freebuff account, used by Cloud chats and every Freebuff Desktop you sign in to.": "为你的 Freebuff 账户提供一个连接，供云端聊天以及你登录的每个 Freebuff 桌面端使用。",
      "Not connected": "未连接",
      "Model providers": "模型服务商",
      "Update needed": "需要更新",
      "This computer": "此电脑",
      "Connected apps": "已连接的应用",
      "Allow popups to connect, then try again.": "请允许弹出窗口以建立连接，然后重试。",
      "Development builds don’t update themselves.": "开发版不会自动更新。",
      "Updates aren’t available in development builds": "开发版无法更新",
      "Could not show the app in Finder. Try again.": "无法在 Finder 中显示应用。请重试。",
      "Use the same Linux account as your browser and check the profile folder’s read permissions. Unlock your login keyring to import encrypted cookies.": "请使用与浏览器相同的 Linux 账户，并检查配置文件夹的读取权限。解锁登录密钥环以导入加密 Cookie。",
      "Could not check browser access. Try again.": "无法检查浏览器访问权限。请重试。",
      "No browsers found": "未找到浏览器",
      "Name and email": "姓名和电子邮件",
      "Account standing": "账户状态",
      "Prepaid credits": "预付额度",
      "No writable repositories found. Update GitHub access in Account settings, then return here.": "未找到可写入的仓库。请在账户设置中更新 GitHub 访问权限，然后返回此处。",
      "Your project uses the folder’s name. You can rename it later.": "项目将使用文件夹名称。你之后可以重命名。",
      "Could not continue this chat on this computer. Please retry.": "无法在此电脑上继续此聊天。请重试。",
      "Make room for": "腾出空间来",
      "Freebuff. Big ideas. Meet your builder. Build your next idea.": "Freebuff。宏大的想法。认识你的构建伙伴。实现你的下一个创意。",
      "Handles missing users": "处理用户缺失的情况",
      "Frontier models like GPT-6.1 Sol and more": "前沿模型，例如 GPT-6.1 Sol 等",
      "One hour of unlimited use, charged when the session starts.": "一小时不限量使用，会话开始时扣费。",
      "Codex updated — model availability refreshed": "Codex 已更新 — 模型可用性已刷新",
      "This provider connection is unavailable. Choose another model or manage your providers.": "此服务商连接不可用。请选择其他模型，或管理服务商。",
