      "Automatic (remote default)": "自动（远程默认）",
      "Cloud transfer failed before import. Choose Local to cancel it. Your queued messages stay paused until you resume.": "导入前云端传输失败。选择“本地”以取消传输。恢复队列前，排队消息会保持暂停。",
      "Bought hours and your plan bonus. Spent after your daily hours.": "已购买的小时额度和方案奖励。在每日额度之后扣除。",
      "Daily grants and session prices are both Freebucks ÷ 5.": "每日赠额和会话价格均为 Freebucks ÷ 5。",
      "My comments on specific lines of the code:": "我对代码中特定行的评论：",
      "Claude Code signs you in with your Claude subscription (`claude setup-token`), on this computer or in a short-lived Cloud VM. Freebuff stores the long-lived token encrypted. Your own Claude Code login is left as it is.": "Claude Code 使用你的 Claude 订阅登录，可在此电脑或短期云端虚拟机上运行（`claude setup-token`）。Freebuff 会加密保存长期令牌，不会更改你自己的 Claude Code 登录状态。",
      "An OpenAI API key runs Codex, and its models also run the Freebuff agent under API providers. While one is saved, Codex uses it instead of your sign-in.": "OpenAI API 密钥可用于运行 Codex，其模型也可通过 API 服务商运行 Freebuff 智能体。保存密钥后，Codex 会使用它而非你的登录凭据。",
      "Real sidebar ad controls with local artwork and no tracking. Use this renderer to check countdown contrast.": "真实的侧边栏广告控件，使用本地素材且不跟踪用户。使用此渲染器检查倒计时对比度。",
      "Committed to its own branch. Nothing was pushed to your repository.": "已提交到其自身分支。没有任何内容推送到你的仓库。",
      "Sponsored tasks need the Freebuff desktop app. Open this project in the app to accept.": "接受赞助任务需要 Freebuff 桌面应用。请在应用中打开此项目。",
